"use client";

import * as React from "react";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "@/lib/utils";
import { ArrowUpRight } from "@/components/ui/icons";

// Link: generated by UIX from the design system. Same variants and sizes as the Figma component.

const linkVariants = cva(
  "skin-quiet inline-flex items-center gap-1 rounded-xs underline-offset-4 hover:underline text-label-medium visited:text-fg-secondary aria-disabled:pointer-events-none aria-disabled:text-fg-disabled focus-visible:outline-none focus-visible:ring-3 focus-visible:ring-line-focus [&_svg]:size-4 [&_svg]:shrink-0",
  {
    variants: {
      color: {
        brand: "text-fg-brand [&_svg]:text-icon-brand",
        neutral: "text-fg-primary [&_svg]:text-icon-primary",
        danger: "text-fg-danger [&_svg]:text-icon-danger",
      },
    },
    defaultVariants: {
      color: "brand",
    },
  },
);

export interface LinkProps
  extends Omit<React.AnchorHTMLAttributes<HTMLAnchorElement>, "color">,
    VariantProps<typeof linkVariants> {
  /** Shows the arrow-up-right icon after the text. */
  showIcon?: boolean;
}

const Link = React.forwardRef<HTMLAnchorElement, LinkProps>(
  ({ className, color, showIcon = false, children, ...props }, ref) => (
    <a data-slot="link" data-kind="control" ref={ref} className={cn(linkVariants({ color }), className)} {...props}>
      {children}
      {showIcon ? <ArrowUpRight aria-hidden /> : null}
    </a>
  ),
);
Link.displayName = "Link";

export { Link, linkVariants };
